function gradeQuiz(questions, answers) {
  let correct = 0;
  const feedback = questions.map(function (question) {
    const answered = Object.prototype.hasOwnProperty.call(answers, question.id);
    const isCorrect = answered &&
      String(answers[question.id]).trim().toLowerCase() ===
      String(question.correctAnswer).trim().toLowerCase();
    if (isCorrect) correct++;
    return { id: question.id, correct: isCorrect, answered: answered };
  });
  const total = questions.length;
  return {
    correct: correct,
    total: total,
    percent: total === 0 ? 0 : Math.round(correct / total * 100),
    feedback: feedback
  };
}
